diff --git a/mailnews/db/msgdb/src/nsMsgDatabase.cpp b/mailnews/db/msgdb/src/nsMsgDatabase.cpp
index 348c3dd0db9..6539138fa12 100644
--- a/mailnews/db/msgdb/src/nsMsgDatabase.cpp
+++ b/mailnews/db/msgdb/src/nsMsgDatabase.cpp
@@ -490,10 +490,14 @@ nsresult nsMsgDatabase::AddHdrToCache(
         return NS_ERROR_OUT_OF_MEMORY;  // XXX out of memory
       }

-      MsgHdrHashElement* element = static_cast<MsgHdrHashElement*>(entry);
-      element->mHdr = hdr;
-      element->mKey = key;
-      NS_ADDREF(hdr);  // make the cache hold onto the header
+      auto* element = static_cast<MsgHdrHashElement*>(entry);
+      nsIMsgDBHdr* oldHdr = element->mHdr;
+      if (oldHdr != hdr) {
+        element->mHdr = hdr;
+        element->mKey = key;
+        NS_ADDREF(hdr);  // make the cache hold onto the header
+        NS_IF_RELEASE(oldHdr);
+      }
       return NS_OK;
     }
   }
@@ -626,8 +630,9 @@ nsresult nsMsgDatabase::RemoveHdrFromCache(nsIMsgDBHdr* hdr, nsMsgKey key) {
     PLDHashEntryHdr* entry =
         m_cachedHeaders->Search((const void*)(uintptr_t)key);
     if (entry) {
+      nsIMsgDBHdr* cachedHdr = static_cast<MsgHdrHashElement*>(entry)->mHdr;
       m_cachedHeaders->Remove((void*)(uintptr_t)key);
-      NS_RELEASE(hdr);  // get rid of extra ref the cache was holding.
+      NS_IF_RELEASE(cachedHdr);  // get rid of extra ref the cache was holding.
     }
   }
   return NS_OK;
diff --git a/mailnews/db/msgdb/test/unit/test_maildb.js b/mailnews/db/msgdb/test/unit/test_maildb.js
index 64c6e11646d..f9c78bb220b 100644
--- a/mailnews/db/msgdb/test/unit/test_maildb.js
+++ b/mailnews/db/msgdb/test/unit/test_maildb.js
@@ -95,3 +95,26 @@ add_task(function test_deletion() {
     localAccountUtils.clearAll();
   }
 });
+
+add_task(function test_stale_delete_cache() {
+  localAccountUtils.loadLocalMailAccount();
+  try {
+    const folder = localAccountUtils.inboxFolder;
+    const db = folder.msgDatabase;
+    const staleHdr = db.attachHdr(db.createNewHdr(), false);
+    const key = staleHdr.messageKey;
+
+    db.getMsgHdrForKey(key);
+    db.forceClosed();
+    folder.msgDatabase = null;
+
+    const reopenedDB = folder.msgDatabase;
+    const freshHdr = reopenedDB.getMsgHdrForKey(key);
+    Assert.notEqual(staleHdr, freshHdr);
+    reopenedDB.deleteHeader(staleHdr, null, false, false);
+    Assert.equal(reopenedDB.getMsgHdrForKey(key), freshHdr);
+    reopenedDB.clearCachedHdrs();
+  } finally {
+    localAccountUtils.clearAll();
+  }
+});
